/* Customer physical inventory inspection. No check automatically resolves a freight incident. */
window.SHInventoryChecks=(()=>{
const pages=['Inventory receipt check'];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID();
function init(c){for(const key of ['inventory','inventoryChecks','freightIncidents','shipments'])if(!Array.isArray(c.store[key]))c.store[key]=[];}
function rowState(item,store){
 const check=(store.inventoryChecks||[]).filter(x=>x.projectId===item.projectId&&x.inventoryId===item.id).slice().sort((a,b)=>String(b.checkedAt||'').localeCompare(String(a.checkedAt||'')))[0];
 const code=item.itemCode||item.bomItemCode;
 const incidents=(store.freightIncidents||[]).filter(x=>x.projectId===item.projectId&&!['resolved','closed'].includes(String(x.status||'').toLowerCase())&&(x.inventoryId===item.id||(!x.inventoryId&&code&&(x.itemCode===code||x.bomItemCode===code))));
 const expectedQty=Number(item.qty),receivedQty=check?Number(check.receivedQty):null,damagedQty=check?Number(check.damagedQty):null;
 const trusted=!!check?.customerConfirmed&&Number.isFinite(expectedQty)&&expectedQty>=0&&Number.isFinite(receivedQty)&&receivedQty>=0&&Number.isFinite(damagedQty)&&damagedQty>=0&&damagedQty<=receivedQty;
 const damaged=(trusted&&damagedQty>0)||incidents.some(x=>/damag|unsafe/i.test(x.type||''));
 const missing=(trusted&&Number.isFinite(expectedQty)&&receivedQty<expectedQty)||incidents.some(x=>/missing|short/i.test(x.type||''));
 const unchecked=!trusted;const complete=trusted&&!damaged&&!missing&&!incidents.length;
 const status=damaged&&missing?'Damage and missing':damaged?'Damaged':missing?'Missing':unchecked?'Not checked':incidents.length?'Incident unresolved':'Checked complete';
 return {check,incidents,damaged,missing,unchecked,complete,status,extraQty:trusted&&Number.isFinite(expectedQty)?Math.max(0,receivedQty-expectedQty):0,expectedQty,receivedQty:trusted?receivedQty:null,damagedQty:trusted?damagedQty:null};
}
function summary(projectId,store){const items=(store.inventory||[]).filter(x=>x.projectId===projectId);const states=items.map(i=>rowState(i,store));return {unchecked:states.filter(s=>s.unchecked).length,damaged:states.filter(s=>s.damaged).length,missing:states.filter(s=>s.missing).length,complete:states.filter(s=>s.complete).length,total:items.length};}
const field=(name,label,value,type='text',extra='')=>`<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
function render(page,c){init(c);if(!pages.includes(page))return '';const items=c.store.inventory.filter(x=>x.projectId===c.projectId),count=summary(c.projectId,c.store);return `<div class="inventory-checks"><div class="heading"><div><div class="eyebrow">CUSTOMER · PHYSICAL DELIVERY CHECK</div><h1>Inventory receipt check</h1><p>${esc(c.project?.name||c.projectId)}</p></div></div><section class="ic-notice"><h2>Check every supplied kitset component</h2><p>The customer receiving the kitset is responsible for a thorough check against the supplied inventory, manifest and identifying labels. Count quantities, inspect condition and photograph discrepancies. Uploading photos or a signed consignment document alone does not complete this inspection.</p><p>Keep damaged goods and packaging separate. Do not install potentially unsafe components. Report differences promptly and ask Shed House to assess them; carrier reporting deadlines depend on the carrier’s terms.</p></section><div class="ic-summary" aria-label="Inventory inspection summary">${[['total','Inventory rows'],['unchecked','Not checked'],['complete','Checked complete'],['damaged','Damaged'],['missing','Missing']].map(([key,label])=>`<div class="card"><strong>${count[key]}</strong><span>${label}</span></div>`).join('')}</div><p class="small">Damaged and missing counts can overlap. Customer checks do not clear unresolved incidents. Additional quantities are flagged for review.</p>${[...new Set(items.map(i=>i.category||'Uncategorised'))].map(category=>`<section class="card"><h2>${esc(category)}</h2>${items.filter(i=>(i.category||'Uncategorised')===category).map(item=>{const state=rowState(item,c.store),check=state.check||{};return `<article class="ic-item"><div class="ic-row-heading"><div><h3>${esc(item.name)}</h3><p>${esc(item.spec||'Specification awaiting Shed House')}<br><span class="small">Item code: ${esc(item.itemCode||item.bomItemCode||'Not supplied')}</span></p></div><span class="tag ${state.complete?'':'amber'}">${esc(state.status)}</span></div><div class="ic-quantities"><span><strong>Expected</strong> ${esc(item.qty)} ${esc(item.unit)}</span><span><strong>Received</strong> ${state.receivedQty==null?'Not checked':esc(state.receivedQty)}</span><span><strong>Damaged</strong> ${state.damagedQty==null?'Not checked':esc(state.damagedQty)}</span>${state.extraQty?`<span class="ic-warning"><strong>Extra received</strong> ${esc(state.extraQty)} · Ask SH to verify</span>`:''}</div>${state.incidents.map(i=>`<div class="ic-incident"><strong>${esc(i.type)} · ${esc(i.status)}${i.hold!==false?' · Material hold':''}</strong><p>${esc(i.description)}</p><p class="small">Reference ${esc(i.caseReference||i.id)} · ${esc(i.decision||'Awaiting Shed House assessment')}</p></div>`).join('')}<details><summary>${state.unchecked?'Check this component':'Review or update physical check'}</summary><form class="ic-form" data-inventory-check="${esc(item.id)}"><p>Expected quantity is ${esc(item.qty)} ${esc(item.unit)} from Shed House inventory. Contact SH if this schedule is incorrect.</p>${field('receivedQty','Actual quantity received',check.receivedQty??'','number','required min="0" step="any"')}${field('damagedQty','Quantity damaged (within received quantity)',check.damagedQty??0,'number','required min="0" step="any"')}<label>Observed condition<select name="condition"><option ${check.condition==='Not yet assessed'?'selected':''}>Not yet assessed</option><option ${check.condition==='No visible damage'?'selected':''}>No visible damage</option><option ${check.condition==='Damage observed'?'selected':''}>Damage observed</option><option ${check.condition==='Needs SH assessment'?'selected':''}>Needs SH assessment</option></select></label>${field('checkedBy','Checked by',check.checkedBy||'','text','required maxlength="150"')}${field('checkedAt','Physical check date and time',check.checkedAt?String(check.checkedAt).slice(0,16):'','datetime-local','required')}<label class="ic-wide">Inspection notes<textarea name="notes" maxlength="4000" rows="3">${esc(check.notes||'')}</textarea></label><label class="ic-check ic-wide"><input type="checkbox" name="customerConfirmed" required> I physically inspected this component and checked labels, the manifest and relevant photos. I understand saving a check does not clear existing freight issues.</label><details class="ic-wide"><summary>Also report a damage / shortage to Shed House</summary><label>Shipment for this project<select name="shipmentId"><option value="">Select shipment</option>${c.store.shipments.filter(s=>s.projectId===c.projectId).map(s=>`<option value="${esc(s.id)}">${esc(s.carrier||'Carrier')} · ${esc(s.trackingNumber||s.id)}</option>`).join('')}</select></label><label class="ic-check"><input type="checkbox" name="reportConfirmed"> I want to create a freight incident for this component, notify the project parties locally and place the shipment on hold for SH assessment.</label><p class="small">Only discrepancies in received or damaged quantities create an incident. No carrier claim or outbound message is submitted.</p></details><p class="ic-error ic-wide" role="alert"></p><button class="primary" type="submit">Save physical check</button></form></details>${check.checkedBy?`<p class="small">Last recorded check: ${esc(check.checkedBy)} · ${esc(check.checkedAt)} · ${esc(check.notes)}</p>`:''}</article>`;}).join('')}</section>`).join('')||'<section class="card"><h2>Inventory awaiting Shed House</h2><p>Ask SH to publish this project’s supplied kitset inventory before checking quantities.</p></section>'}</div>`;}
function bind(page,c){init(c);document.querySelectorAll('[data-inventory-check]').forEach(form=>form.onsubmit=e=>{e.preventDefault();const error=form.querySelector('.ic-error');error.textContent='';const d=Object.fromEntries(new FormData(form));const item=c.store.inventory.find(i=>i.id===form.dataset.inventoryCheck&&i.projectId===c.projectId);const fail=message=>{error.textContent=message;};if(!item)return fail('This project inventory item is unavailable.');const expected=Number(item.qty),received=Number(d.receivedQty),damaged=Number(d.damagedQty);if(d.receivedQty===''||d.damagedQty===''||!Number.isFinite(expected)||expected<0||!Number.isFinite(received)||received<0||!Number.isFinite(damaged)||damaged<0)return fail('Expected, received and damaged quantities must be finite, non-negative numbers.');if(damaged>received)return fail('Damaged quantity cannot exceed the quantity received.');if(!d.customerConfirmed||!d.checkedBy.trim()||!d.checkedAt||!Number.isFinite(new Date(d.checkedAt).getTime()))return fail('Provide the checker, valid inspection date and physical-check confirmation.');if(d.condition==='Not yet assessed')return fail('Inspect and record the component condition before confirming the check.');if((damaged>0&&d.condition==='No visible damage')||(damaged===0&&d.condition==='Damage observed'))return fail('Recorded condition must match the damaged quantity.');const missingQty=Math.max(0,expected-received);const status=damaged>0&&missingQty>0?'Damage and missing':damaged>0?'Damaged':missingQty>0?'Missing':'Checked complete';const shipment=d.reportConfirmed?c.store.shipments.find(s=>s.id===d.shipmentId&&s.projectId===c.projectId):null;if(d.reportConfirmed&&!shipment)return fail('Select a shipment for this project to report an incident.');if(d.reportConfirmed&&damaged===0&&missingQty===0)return fail('No damaged or missing quantities were recorded. Save the check without reporting an incident.');const now=new Date().toISOString();const check={id:uid(),projectId:c.projectId,inventoryId:item.id,checkedBy:d.checkedBy.trim(),checkedAt:d.checkedAt,receivedQty:received,damagedQty:damaged,status,notes:d.notes,condition:d.condition,customerConfirmed:true,recordedAt:now};const old=c.store.inventoryChecks.findIndex(x=>x.projectId===c.projectId&&x.inventoryId===item.id);if(old<0)c.store.inventoryChecks.push(check);else c.store.inventoryChecks[old]=check;
if(d.reportConfirmed){const incident={id:uid(),projectId:c.projectId,shipmentId:shipment.id,inventoryId:item.id,itemCode:item.itemCode||item.bomItemCode||'',sourceBOMId:item.sourceBOMId||null,type:status,item:item.name,qty:damaged+missingQty,expectedQty:expected,receivedQty:received,damagedQty:damaged,missingQty,unit:item.unit,description:`Physical inventory check: expected ${expected} ${item.unit||''}; actually received ${received}; damaged within received ${damaged}; missing ${missingQty}. Affected quantity ${damaged+missingQty} represents damage plus shortage. ${d.notes||''}`,status:'Reported',hold:true,source:'Inventory receipt check',inventoryCheckId:check.id,createdAt:now,owner:'customer',decision:'',caseReference:'',attachments:[],history:[{at:now,owner:d.checkedBy.trim(),status:'Reported',note:'Customer explicitly reported physical inventory discrepancy; hold pending SH assessment.'}]};c.store.freightIncidents.push(incident);shipment.status='On hold';shipment.events??=[];shipment.events.push({id:uid(),status:'On hold',location:shipment.destination||'',note:`Inventory incident ${incident.id}: ${item.name}`,at:now,source:'Manual'});c.notify({title:'Kitset inventory discrepancy reported',message:incident.description,roles:['staff','customer','contractor'],projectId:c.projectId,kind:'freight-incident'});}c.save();c.toast(d.reportConfirmed?'Physical check and freight incident saved locally. Shipment held for SH assessment.':'Physical inventory check saved. Existing incident holds remain unchanged.');c.navigate(page);});}
return {pages,render,bind,summary,rowState};
})();
